INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-26', 'es', 'LAIKA 64 3.6.2: juego en línea más estable', 'El retraso en línea ya no sube y baja con conexiones con altibajos: partidas más fluidas. El chat de la sala acomoda los mensajes largos y la etiqueta Avatar premium ya no se sale. Actualiza desde LAIKA.'),
 ('2026-11-26', 'en', 'LAIKA 64 3.6.2: more stable online play', 'The online delay no longer goes up and down on links with jitter: smoother games. The room chat wraps long messages and the Premium avatar tag stays in its card. Update from LAIKA.'),
 ('2026-11-26', 'pt', 'LAIKA 64 3.6.2: jogo online mais estável', 'O atraso online não sobe e desce mais em conexões instáveis: partidas mais fluidas. O chat da sala ajusta as mensagens longas e a etiqueta Avatar premium não sai mais do cartão. Atualize pelo LAIKA.'),
 ('2026-11-26', 'fr', 'LAIKA 64 3.6.2 : jeu en ligne plus stable', 'Le délai en ligne ne monte et ne descend plus avec les connexions instables : parties plus fluides. Le chat de la salle range les longs messages et le badge Avatar premium reste dans sa carte. Mets à jour depuis LAIKA.'),
 ('2026-11-26', 'de', 'LAIKA 64 3.6.2: stabileres Online-Spiel', 'Die Online-Verzögerung schwankt bei unruhigen Verbindungen nicht mehr: flüssigere Spiele. Der Raum-Chat bricht lange Nachrichten um und das Premium-Avatar-Abzeichen bleibt in seiner Karte. Aktualisiere in LAIKA.'),
 ('2026-11-26', 'it', 'LAIKA 64 3.6.2: gioco online più stabile', 'Il ritardo online non sale e scende più con le connessioni instabili: partite più fluide. La chat della stanza manda a capo i messaggi lunghi e il badge Avatar premium resta nella sua scheda. Aggiorna da LAIKA.'),
 ('2026-11-26', 'ru', 'LAIKA 64 3.6.2: стабильнее онлайн-игра', 'Онлайн-задержка больше не скачет при нестабильном соединении: игры плавнее. Чат комнаты переносит длинные сообщения, а значок премиум-аватара не выходит за карточку. Обновись из LAIKA.');
